#include <chrono>
#include <iomanip>
#include <iostream>
#include <cstdint>
#include <string>

#include "Halide.h"

// include common PolyBench-style definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (N, etc.)
#include "nussinov.hpp"

using num_t  = DATA_TYPE;   // table element type
using base_t = int8_t;      // RNA base type (0..3), equivalent to 'char' in original code

using namespace Halide;

// -----------------------------------------------------------------------------
// Array initialization, translated to Halide
// -----------------------------------------------------------------------------
static
void init_array(int n,
                Halide::Buffer<base_t, 1> seq,
                Halide::Buffer<num_t,  2> table) {
    Var i("i"), j("j");

    // Initialize RNA sequence: seq[i] = (i+1) % 4  (values in [0,3])
    Func init_seq("init_seq");
    init_seq(i) = cast<base_t>((i + 1) % 4);

    // Initialize DP table to 0
    // C layout: table[i][j]; Halide layout: table(x=j, y=i)
    Func init_table("init_table");
    init_table(j, i) = cast<num_t>(0);

    init_seq.realize(seq);
    init_table.realize(table);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    //  - seq: 1D of length n
    //  - table: 2D, layout (x=j, y=i) with extents (n, n)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t,  2> table(n, n);
    Halide::Buffer<num_t,  2> table_tmp(n, n);  // scratch buffer for double-buffering

    // Initialize data
    init_array(n, seq, table);

    // -----------------------------
    // Build Halide DP step pipeline
    // -----------------------------

    // Image parameters for the current DP table and the sequence
    ImageParam table_in(type_of<num_t>(), 2, "table_in");   // (x=j, y=i)
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");

    // Scalar parameters: problem size and current band length
    Param<int> n_param("n");
    Param<int> len("len");

    // Func that computes the updated value for the diagonal j = i + len
    // For a fixed len, for i in [0, n-len), j = i + len:
    // This computes table[i][j] according to the original recurrence.
    Var i("i");

    Func step_diag("step_diag");

    // j index for the cell (i,j) being updated
    Expr j = i + len;

    // Base value: existing table[i][j]
    // table[i][j]  -> table_in(x=j, y=i)
    Expr v0 = table_in(j, i);

    // table[i][j-1]
    Expr v_left = table_in(j - 1, i);

    // table[i+1][j]
    Expr v_down = table_in(j, i + 1);

    // Take max with neighbors (as in the first two max_score clauses)
    Expr v1 = max(v0, v_left);
    Expr v2 = max(v1, v_down);

    // Pairing term involving seq[i], seq[j] and table[i+1][j-1]
    // table[i+1][j-1] -> table_in(x=j-1, y=i+1)
    Expr v_diag = table_in(j - 1, i + 1);

    // match(seq[i], seq[j]) == 1 iff seq[i] + seq[j] == 3, else 0
    Expr b1 = cast<int32_t>(seq_param(i));
    Expr b2 = cast<int32_t>(seq_param(j));

    Expr match_val = select(b1 + b2 == 3,
                            cast<num_t>(1),
                            cast<num_t>(0));

    // If i < j-1, allow adding match; else just take table[i+1][j-1]
    Expr pair_term = select(i < j - 1,
                            v_diag + match_val,
                            v_diag);

    Expr v3 = max(v2, pair_term);

    // Now handle the split case:
    // for (k = i+1; k < j; k++)
    //     table[i][j] = max(table[i][j], table[i][k] + table[k+1][j]);
    //
    // We express this as a reduction over r in [0, len-1), with
    // k = i + 1 + r, so k runs from i+1 to j-1.
    RDom r(0, len - 1, "r");  // extent is (len-1); when len == 1, extent = 0

    Expr k = i + 1 + r;

    // table[i][k]     -> table_in(x=k,   y=i)
    // table[k+1][j]   -> table_in(x=j,   y=k+1)
    step_diag(i) = v3;
    step_diag(i) = max(step_diag(i),
                       table_in(k, i) + table_in(j, k + 1));

    // Func that applies the updated diagonal back to the full table:
    // updated(x,y) = step_diag(y) if x == y + len and 0 <= y < n-len,
    //                otherwise table_in(x,y).
    Var x("x"), y("y");
    Func updated("updated");

    Expr on_diag = (x == y + len) &&
                   (y >= 0) &&
                   (y < n_param - len) &&
                   (x >= 0) &&
                   (x < n_param);

    updated(x, y) = select(on_diag,
                           step_diag(y),
                           table_in(x, y));

    // A simple schedule: iterate over y (rows) outside, x (columns) inside.
    updated.reorder(x, y);

    // Build a Pipeline and JIT-compile it once
    Pipeline pipeline(updated);

    Target target = get_host_target();
    pipeline.compile_jit(target);

    // Bind inputs that are invariant across iterations
    seq_param.set(seq);
    n_param.set(n);

    // ------------------------------------
    // Run the dynamic programming algorithm
    // ------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // table holds the current DP table; table_tmp is scratch
    table_in.set(table);

    for (int len_val = 1; len_val < n; ++len_val) {
        len.set(len_val);

        // Compute updated table for this band length into table_tmp
        pipeline.realize(table_tmp);

        // Swap current and temporary tables
        std::swap(table, table_tmp);
        table_in.set(table);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // ------------------------------------
    // Print results to avoid dead-code elim
    // ------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        // Original print_array prints table[i][j] for i <= j
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                // C layout: table[i][j]; Halide layout: table(x=j, y=i)
                std::cerr << table(j, i) << '\n';
            }
        }
    }

    // Print the elapsed time (seconds) on stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
