using num_t  = DATA_TYPE;   // table element type
using base_t = int8_t;      // RNA base type (0..3)

using namespace Halide;

/**
 * Initialize the sequence and DP table.
 *
 * C reference:
 *   for (i=0; i<n; i++) seq[i] = (base)((i+1)%4);
 *   for (i=0; i<n; i++)
 *     for (j=0; j<n; j++)
 *       table[i][j] = 0;
 */
static void init_array(int n,
                       Buffer<base_t, 1> seq,
                       Buffer<num_t,  2> table) {
    Var i("i"), j("j");

    // seq[i] = (i+1) % 4;
    Func init_seq("init_seq");
    init_seq(i) = cast<base_t>((i + 1) % 4);

    // table[i][j] = 0;
    // We store table[i][j] in Halide as table(j, i) (column-major in x)
    Func init_table("init_table");
    init_table(j, i) = cast<num_t>(0);

    init_seq.realize(seq);
    init_table.realize(table);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    //  - seq[i]   : bases in range [0,3]
    //  - table[i][j] : DP table (we store as table(j, i) in Halide)
    Buffer<base_t, 1> seq(n);
    Buffer<num_t,  2> table(n, n); // dim 0 = j, dim 1 = i

    // Initialize inputs
    init_array(n, seq, table);

    // Create Halide ImageParams that refer to these buffers.
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    seq_param.set(seq);
    table_param.set(table);

    // Parameter for current subsequence length (j - i).
    Param<int> len_param("len");

    // Define the per-length update as a 1D Halide Func.
    //
    // For a given 'len', we compute the values for all pairs (i, j=i+len),
    // with i in [0, n-len). For each such pair we implement the same
    // recurrence as in the original C code:
    //
    //   table[i][j] = max( table[i][j-1],
    //                      table[i+1][j],
    //                      (i<j-1 ? table[i+1][j-1]+match(seq[i],seq[j])
    //                              : table[i+1][j-1]),
    //                      max_{k=i+1..j-1}( table[i][k] + table[k+1][j] ) )
    //
    // using only values from previously-computed shorter subsequences.
    Var i("i");
    Func band("band");

    Expr len = len_param;
    Expr j = i + len; // j index corresponding to band(i)

    // Current value (from previous iterations). In this algorithm,
    // table[i][j] is initially 0 and is only written once (when len = j - i),
    // but we keep the term to stay faithful to the C code.
    Expr cur = table_param(j, i); // table[i][j]

    Expr best = cur;

    // max_score(table[i][j], table[i][j-1]);
    // C indices: table[i][j-1] => table_param(j-1, i)
    best = Halide::max(best, table_param(j - 1, i));

    // max_score(table[i][j], table[i+1][j]);
    // C indices: table[i+1][j] => table_param(j, i+1)
    best = Halide::max(best, table_param(j, i + 1));

    // Adjacency / pairing term:
    //
    // if (j-1 >= 0 && i+1 < N) {
    //   if (i < j-1)
    //     table[i][j] = max(table[i][j], table[i+1][j-1] + match(seq[i], seq[j]));
    //   else
    //     table[i][j] = max(table[i][j], table[i+1][j-1]);
    // }
    //
    // Given our choice of i-domain and len >= 1, the bounds checks are always
    // satisfied, so we can omit them here.
    Expr si = cast<int>(seq_param(i));
    Expr sj = cast<int>(seq_param(j));

    // match(b1,b2) = (b1 + b2 == 3 ? 1 : 0)
    Expr match_val = select(si + sj == 3,
                            cast<num_t>(1),
                            cast<num_t>(0));

    // table[i+1][j-1] -> table_param(j-1, i+1)
    Expr pair_base = table_param(j - 1, i + 1);
    Expr pair_candidate = select(i < j - 1,
                                 pair_base + match_val,
                                 pair_base);

    best = Halide::max(best, pair_candidate);

    // Split term:
    //
    // for (k = i+1; k < j; k++)
    //   table[i][j] = max(table[i][j], table[i][k] + table[k+1][j]);
    //
    // Let k_idx = i + 1 + k_off, where k_off in [0, len-2] (for len >= 2).
    // table[i][k_idx]     -> table_param(k_idx, i)
    // table[k_idx+1][j]   -> table_param(j, k_idx+1)
    RDom k_off(0, len_param - 1, "k_off"); // extent = len-1; 0 iterations when len == 1

    Expr k_idx = i + 1 + k_off;
    Expr split_candidate = table_param(k_idx, i) +
                           table_param(j, k_idx + 1);

    band(i) = best;
    band(i) = Halide::max(band(i), split_candidate);

    // Reorder to match the natural traversal over i.
    band.reorder(i);

    // Bind parameters and JIT-compile the per-length pipeline
    band.compile_jit();

    // Time just the dynamic-programming kernel.
    auto t_start = std::chrono::high_resolution_clock::now();

    // For lengths from 1 to n-1, compute band(i) for i in [0, n-len),
    // and scatter the results back into the appropriate entries of table.
    for (int len_val = 1; len_val < n; ++len_val) {
        len_param.set(len_val);

        // band is 1D in 'i', of size n - len
        Buffer<num_t, 1> band_buf(n - len_val);
        band.realize(band_buf);

        // Scatter back: band(i) corresponds to table[i][j=i+len]
        for (int i_val = 0; i_val < n - len_val; ++i_val) {
            int j_val = i_val + len_val;
            table(j_val, i_val) = band_buf(i_val);
        }
    }

    auto t_end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(t_end - t_start);

    // Optionally print the resulting DP table, similar in spirit to
    // PolyBench's print_array (prints upper triangle).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        int t = 0;
        std::cerr << std::fixed << std::setprecision(2);
        for (int i_row = 0; i_row < n; ++i_row) {
            for (int j_col = i_row; j_col < n; ++j_col) {
                if (t % 20 == 0) {
                    std::cerr << "\n";
                }
                std::cerr << table(j_col, i_row) << " ";
                ++t;
            }
        }
        std::cerr << "\n";
    }

    // Print elapsed time (seconds) as in the example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
