#include <chrono>
#include <iomanip>
#include <iostream>
#include <cstdint>

#include "Halide.h"

// include common definitions (defines N, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (defines N for this kernel)
#include "nussinov.hpp"

using num_t  = DATA_TYPE;
using base_t = uint8_t;

using namespace Halide;

// Host-side helpers mirroring the original C macros.
inline int match_base(base_t b1, base_t b2) {
    // bases are in [0,3]; a match is when b1 + b2 == 3
    return (static_cast<int>(b1) + static_cast<int>(b2)) == 3 ? 1 : 0;
}

inline num_t max_score(num_t s1, num_t s2) {
    return (s1 >= s2) ? s1 : s2;
}

// Array initialization: seq is length-n, table is n x n (all zeros).
static void init_array(int n,
                       Halide::Buffer<base_t, 1> seq,
                       Halide::Buffer<num_t, 2> table) {
    Var i("i"), j("j");
    Func init_seq("init_seq"), init_table("init_table");

    // seq[i] = (base)((i+1) % 4)
    init_seq(i) = cast<base_t>((i + 1) % 4);

    // table[i][j] = 0 for all i,j
    // In C: table[i][j]; we map to table(j, i) in Halide.
    init_table(j, i) = cast<num_t>(0);

    init_seq.realize(seq);
    init_table.realize(table);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // seq[i] in C  -> seq(i) in Halide (1D)
    // table[i][j] in C -> table(j, i) in Halide (2D, x=j, y=i)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2> table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // --------------------------------------------------------------------
    // Halide kernel for the inner k-loop:
    //
    // Given current table and fixed (i,j), compute:
    //   max_{k = i+1..j-1} ( table[i][k] + table[k+1][j] )
    //
    // We implement this as a scalar Func split_max(), using an RDom over k.
    // --------------------------------------------------------------------
    ImageParam table_param(type_of<num_t>(), 2, "table_param");
    Param<int> i_param("i_param");
    Param<int> j_param("j_param");
    Param<int> n_param("n_param");

    // Reduction domain over k in [0, n_param-2]; j-1 <= n-2, so k+1 is always in-bounds.
    RDom r_k(0, n_param - 1, "r_k");

    Func split_max("split_max");
    split_max() = cast<num_t>(0);

    // table[i][k]  -> table_param(k, i)
    // table[k+1][j]-> table_param(j, k+1)
    // Only contribute when (k > i && k < j); otherwise add 0.
    split_max() = max(
        split_max(),
        select((r_k > i_param) && (r_k < j_param),
               table_param(r_k, i_param) + table_param(j_param, r_k + 1),
               cast<num_t>(0))
    );

    // Bind the table buffer and n once.
    table_param.set(table);
    n_param.set(n);

    // JIT-compile the Halide reduction.
    split_max.compile_jit(get_host_target());

    // --------------------------------------------------------------------
    // Main Nussinov DP, executed on the host, using Halide only for the k-loop.
    //
    // This mirrors the original C kernel:
    //
    // for (i = n-1; i >= 0; i--) {
    //   for (j = i+1; j < n; j++) {
    //     ... updates based on table and seq ...
    //     for (k = i+1; k < j; k++) {
    //        table[i][j] = max_score(table[i][j], table[i][k] + table[k+1][j]);
    //     }
    //   }
    // }
    //
    // Except that the inner k-loop is done via the Halide reduction.
    // --------------------------------------------------------------------
    using clock = std::chrono::high_resolution_clock;
    auto start  = clock::now();

    for (int i = n - 1; i >= 0; --i) {
        for (int j = i + 1; j < n; ++j) {
            // C: table[i][j]
            num_t best = table(j, i);

            // if (j-1 >= 0) table[i][j] = max(table[i][j], table[i][j-1]);
            if (j - 1 >= 0) {
                best = max_score(best, table(j - 1, i));
            }

            // if (i+1 < n) table[i][j] = max(table[i][j], table[i+1][j]);
            if (i + 1 < n) {
                best = max_score(best, table(j, i + 1));
            }

            // if (j-1 >= 0 && i+1 < n) { ... }
            if (j - 1 >= 0 && i + 1 < n) {
                num_t cand = table(j - 1, i + 1); // table[i+1][j-1]

                // if (i < j-1) cand += match(seq[i], seq[j]);
                if (i < j - 1) {
                    int m = match_base(seq(i), seq(j));
                    cand += static_cast<num_t>(m);
                }

                best = max_score(best, cand);
            }

            // Inner k-loop via Halide reduction:
            // for (k = i+1; k < j; k++)
            //   best = max(best, table[i][k] + table[k+1][j]);
            if (j - i >= 2) { // only if the k-range is non-empty
                i_param.set(i);
                j_param.set(j);

                Halide::Realization r = split_max.realize();
                Halide::Buffer<num_t> tmp = r[0];
                num_t split_val = tmp();

                best = max_score(best, split_val);
            }

            // Write back updated value
            table(j, i) = best;
        }
    }

    auto end      = clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print the upper-triangular part of the table,
    // similar to the original PolyBench print_array().
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        int t = 0;
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                if ((t % 20) == 0) {
                    std::cerr << "\n";
                }
                std::cerr << table(j, i) << ' ';
                ++t;
            }
        }
        std::cerr << "\n";
    }

    // Print elapsed time in seconds (as PolyBench would print).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
