#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (N, DATA_TYPE, etc.)
#include "nussinov.hpp"

using num_t = DATA_TYPE;
using base_t = char;

using namespace Halide;

/**
 * Initialize the sequence and DP table.
 *
 * seq[i] = (i+1) % 4  (RNA bases encoded as 0..3)
 * table[i][j] = 0
 *
 * C layout: table[i][j]
 * Halide layout: table(j, i)
 */
static
void init_array(int n,
                Halide::Buffer<base_t, 1> seq,
                Halide::Buffer<num_t, 2> table) {
    Var i("i"), j("j");

    Func init_seq("init_seq"), init_table("init_table");

    // base is AGCT/0..3
    init_seq(i)    = cast<base_t>((i + 1) % 4);
    init_table(j,i) = cast<num_t>(0);

    init_seq.realize(seq);
    init_table.realize(table);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // seq[i]  -> seq(i)
    // table[i][j] -> table(j, i)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2> table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // Halide parameters and inputs
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam prev_table(type_of<num_t>(), 2, "prev_table");
    Param<int> gap("gap");  // current (j - i) we are computing

    // Bind initial buffers
    seq_param.set(seq);
    prev_table.set(table);

    // Vars and expressions
    Var i("i");              // corresponds to C index i (row)
    Expr j = i + gap;        // j = i + gap (column index)

    // Reduction domain for splitting k
    // k runs from 0 to (n-2); we use prev_table.dim(0).extent() (== n)
    // and subtract 1 to get an extent of (n-1) -> k in [0, n-2].
    RDom k(0, prev_table.dim(0).extent() - 1, "k");

    // Compute best split score for a given (i, j=i+gap):
    // best_split(i) = max_{k in (i, j)} prev_table[i][k] + prev_table[k+1][j]
    // In Halide layout:
    //   table[i][k]   -> prev_table(k, i)
    //   table[k+1][j] -> prev_table(j, k+1)
    Func best_split("best_split");

    best_split(i) = cast<num_t>(0);

    Expr cond_k   = (k > i) && (k < j);
    Expr split_candidate =
        prev_table(k, i) + prev_table(j, k + 1);

    best_split(i) = select(cond_k,
                           max(best_split(i), split_candidate),
                           best_split(i));

    // Main DP step for a fixed gap:
    // Compute the value for table[i][j] (j = i + gap) using the
    // Nussinov recurrence:
    //
    // dp[i][j] = max {
    //   dp[i][j-1],
    //   dp[i+1][j],
    //   (if i < j-1) dp[i+1][j-1] + match(seq[i], seq[j])
    //   else         dp[i+1][j-1],
    //   max_{k in (i,j)} dp[i][k] + dp[k+1][j]
    // }
    //
    // In Halide layout, table[i][j] == prev_table(j, i).
    Func step("step");

    // table[i][j-1] -> prev_table(j-1, i)
    Expr left = prev_table(j - 1, i);
    // table[i+1][j] -> prev_table(j, i + 1)
    Expr down = prev_table(j, i + 1);
    // table[i+1][j-1] -> prev_table(j - 1, i + 1)
    Expr diag_prev = prev_table(j - 1, i + 1);

    // match(seq[i], seq[j]) = ((seq[i] + seq[j]) == 3 ? 1 : 0)
    Expr seq_i = cast<int>(seq_param(i));
    Expr seq_j = cast<int>(seq_param(j));
    Expr match_score = select(seq_i + seq_j == 3,
                              cast<num_t>(1),
                              cast<num_t>(0));

    // Don't allow adjacent elements to bond: if i < j-1, add match_score,
    // else just take diag_prev.
    Expr pair_score =
        select(i < j - 1,
               diag_prev + match_score,
               diag_prev);

    // Combine all candidates
    Expr best_neighbor = max(left, down);
    best_neighbor      = max(best_neighbor, pair_score);
    best_neighbor      = max(best_neighbor, best_split(i));

    step(i) = best_neighbor;

    // JIT-compile the kernel
    step.compile_jit();

    // Measure execution time of the main DP kernel.
    auto start = std::chrono::high_resolution_clock::now();

    // Dynamic programming over increasing gap = j - i
    // Original C:
    //   for (i = n-1; i >= 0; i--)
    //     for (j = i+1; j < n; j++)
    //
    // is equivalent to:
    //   for (gap = 1; gap < n; gap++)
    //     for (i = 0; i < n - gap; i++)
    //       j = i + gap
    //
    // Here, we drive 'gap' on the host, and for each gap we ask Halide
    // to compute all dp[i][i+gap] (a full anti-diagonal) in one call.
    for (int d = 1; d < n; d++) {
        gap.set(d);
        // prev_table always refers to the current state of 'table'
        prev_table.set(table);

        int len = n - d; // number of i values for this gap
        Halide::Buffer<num_t, 1> diag(len);

        // Compute dp[i][i+d] for i in [0, len-1]
        step.realize(diag);

        // Write results back into the DP table:
        // table[i][j] -> table(j, i) in Halide layout.
        for (int ii = 0; ii < len; ii++) {
            int jj = ii + d;
            table(jj, ii) = diag(ii);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results to avoid dead-code elimination (and optionally
    // check correctness). We print the full table here.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                std::cerr << table(j, i) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
